-- Isolated PostgreSQL fixture for the existing tables used by the new migration.
CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,raw_user_meta_data jsonb);
CREATE TABLE public.profiles(user_id uuid PRIMARY KEY,username text,display_name text,avatar_url text,created_at timestamptz DEFAULT now());
CREATE TABLE public.brands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,name text,slug text,latitude double precision,longitude double precision);
CREATE TABLE public.campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brand_id uuid REFERENCES brands(id),name text,reward_type text,reward_amount numeric,slots integer,slots_filled integer DEFAULT 0,platform_fee_pct numeric,total_budget numeric,funded boolean,pay_mode text,status text,target_city text,target_state text,physical_item text,deadline_hours integer,campaign_kind text,phases jsonb,auto_accept boolean DEFAULT false);
CREATE TABLE public.campaign_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid REFERENCES campaigns(id),influencer_user_id uuid,status text,delivery_url text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(campaign_id,influencer_user_id));
CREATE TABLE public.follows(id uuid DEFAULT gen_random_uuid(),follower_id uuid REFERENCES auth.users(id),following_id uuid REFERENCES auth.users(id),UNIQUE(follower_id,following_id),CHECK(follower_id<>following_id));
ALTER TABLE follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Follows are viewable by everyone" ON follows FOR SELECT USING(true);
CREATE POLICY "Authenticated users can follow" ON follows FOR INSERT WITH CHECK(auth.uid()=follower_id);
CREATE POLICY "Users can unfollow" ON follows FOR DELETE USING(auth.uid()=follower_id);
CREATE TABLE public.ratings(id uuid DEFAULT gen_random_uuid(),application_id uuid,rater_user_id uuid,rated_user_id uuid,stars integer CHECK(stars BETWEEN 1 AND 5),comment text,created_at timestamptz DEFAULT now(),criteria jsonb DEFAULT '{}',UNIQUE(application_id,rater_user_id));
ALTER TABLE ratings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "ratings viewable" ON ratings FOR SELECT USING(true);
CREATE POLICY "rate as self" ON ratings FOR INSERT TO authenticated WITH CHECK(rater_user_id=auth.uid());
CREATE TABLE public.conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.conversation_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid REFERENCES conversations(id),user_id uuid,joined_at timestamptz DEFAULT now(),last_read_at timestamptz DEFAULT now(),UNIQUE(conversation_id,user_id));
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid REFERENCES conversations(id),sender_id uuid,content text,created_at timestamptz DEFAULT now());
ALTER TABLE conversations ENABLE ROW LEVEL SECURITY; ALTER TABLE conversation_participants ENABLE ROW LEVEL SECURITY; ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_conversation_participant(_conversation_id uuid,_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM conversation_participants WHERE conversation_id=_conversation_id AND user_id=_user_id)$$;
CREATE POLICY "Users can view own conversations" ON conversations FOR SELECT USING(public.is_conversation_participant(id,auth.uid()));
CREATE POLICY "Authenticated users can create conversations" ON conversations FOR INSERT WITH CHECK(auth.uid() IS NOT NULL);
CREATE POLICY "Users can view participants of their conversations" ON conversation_participants FOR SELECT USING(public.is_conversation_participant(conversation_id,auth.uid()));
CREATE POLICY "Authenticated users can add participants" ON conversation_participants FOR INSERT WITH CHECK(auth.uid() IS NOT NULL);
CREATE POLICY "Users can update own participation" ON conversation_participants FOR UPDATE USING(user_id=auth.uid());
CREATE POLICY "Users can leave conversations" ON conversation_participants FOR DELETE USING(user_id=auth.uid());
CREATE POLICY "Users can view messages in their conversations" ON messages FOR SELECT USING(public.is_conversation_participant(conversation_id,auth.uid()));
CREATE POLICY "Users can send messages to their conversations" ON messages FOR INSERT WITH CHECK(sender_id=auth.uid() AND public.is_conversation_participant(conversation_id,auth.uid()));
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid DEFAULT gen_random_uuid(),bucket_id text REFERENCES storage.buckets(id),name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql AS $$SELECT string_to_array(name,'/')$$;
GRANT USAGE ON SCHEMA public,auth,storage TO authenticated,anon,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon;
GRANT SELECT,INSERT,DELETE ON storage.objects TO authenticated;
